#!/usr/bin/env bash
# validate-tsx.sh — PostToolUse hook for VS Code Copilot
# Validates that TSX component files follow the shared core convention
# (sanruiz-mall-frontend-starter). See CLAUDE.md § Component Structure & Naming.
# Exit 0 = pass, Exit 1 = fail (shown as warning to Copilot).

set -euo pipefail

FILE="${COPILOT_FILE:-}"

if [[ -z "$FILE" ]]; then
  exit 0
fi

if [[ "$FILE" != *.tsx ]]; then
  exit 0
fi

# Only validate files inside components/ directories
if [[ "$FILE" != *"/components/"* ]]; then
  exit 0
fi

# components/ui/ is generated by `npx shadcn add` — it follows shadcn's own
# conventions and is not ours to reshape.
if [[ "$FILE" == *"/components/ui/"* ]]; then
  exit 0
fi

BASENAME=$(basename "$FILE")
DIRNAME=$(basename "$(dirname "$FILE")")

# Tests are colocated next to the component; they have their own naming.
if [[ "$DIRNAME" == "__tests__" || "$BASENAME" == *.test.tsx ]]; then
  exit 0
fi

ERRORS=()

# --- Rule 1: flat kebab-case.tsx, never index.tsx, never PascalCase ---
if [[ "$BASENAME" == "index.tsx" ]]; then
  ERRORS+=("Components are flat kebab-case files now, not <folder>/index.tsx (see CLAUDE.md)")
elif [[ ! "$BASENAME" =~ ^[a-z][a-z0-9]*(-[a-z0-9]+)*\.tsx$ ]]; then
  ERRORS+=("Component file must be kebab-case, e.g. entity-card.tsx (found: $BASENAME)")
fi

# --- Rule 2: named export, not default ---
if [[ -f "$FILE" ]]; then
  if grep -qE "^export default" "$FILE"; then
    ERRORS+=("Components use a named 'export function PascalName', not 'export default'")
  fi

  if ! grep -qE "^export (async )?function [A-Z]|^export \{ *[A-Z]" "$FILE"; then
    ERRORS+=("Component must export a PascalCase function, e.g. 'export function EntityCard(...)'")
  fi
fi

# --- Rule 3: No relative imports (must use @/ prefix) ---
if [[ -f "$FILE" ]]; then
  if grep -qE "^import .+ from ['\"]\.\.?/" "$FILE" || grep -qE "^import ['\"]\.\.?/" "$FILE"; then
    ERRORS+=("Relative imports found. Use absolute imports with @/ prefix instead of ./ or ../")
  fi
fi

# --- Report ---
if [[ ${#ERRORS[@]} -gt 0 ]]; then
  echo "⚠️  TSX validation issues in: $FILE"
  for err in "${ERRORS[@]}"; do
    echo "  • $err"
  done
  exit 1
fi

exit 0
